clear;
clc;
close all;

addpath("euler");
addpath("transfer_function");

%Run euler model
[time, euler_position] = euler_sim();

%Run transfer function
[~, tf_position] = tf_model(time);

figure; %[output:093d26b6]
plot(time, euler_position, 'b-', 'LineWidth', 1.5); %[output:093d26b6]
hold on; %[output:093d26b6]
plot(time, tf_position, 'r--', 'LineWidth', 1.5); %[output:093d26b6]

xlabel('Time (s)'); %[output:093d26b6]
ylabel('Position (m)'); %[output:093d26b6]
title('Euler Model vs. Transfer Function'); %[output:093d26b6]

legend('Euler Model', 'Transfer Function', 'Location', 'best'); %[output:093d26b6]

grid on; %[output:093d26b6]
hold off; %[output:093d26b6]



